allowRecommend[users[i]] = true;
userisBuyCarTypeOf[users[i]][typeOfs[i]] = true;
}
}

function addUserGuild(address[] memory users, uint256[] memory guildTypes) external onlyOwner {
for(uint256 i = 0; i < users.length; i++) {
