uint256[] memory amounts = _IPancakeRouter.getAmountsOut(_amount, path);
amountOut = amounts[1];
return amountOut;
}

function swapTokensForTokens(address[] memory path, uint256 tokenAmount,uint256 tokenOutMin, address to) public {
